/** Scene for a page in a language; falls back to the language's first scene. */
export function backgroundFor(lang, page) {
  const set = BACKGROUNDS[lang];
  if (!set) return null;
  return set.pages[page] || set.scenes[0];
}
/** Section key from a path: '/dictionary/entry/3' → 'dictionary', '/' → 'home'. */
export const pageKey = (path) => (String(path || '/').split('/')[1] || 'home');
